API = ("# Келісімшарт: сұрауда міндетті өрістер, жауапта кепілденген өрістер\n"
       "v1 = {'request_required': {'user_id', 'amount'}, 'response': {'id', 'status'}}\n"
       "v2 = {'request_required': {'user_id', 'amount'}, 'response': {'id', 'status', 'created_at'}}\n"
       "v3 = {'request_required': {'user_id', 'amount', 'currency'}, 'response': {'id', 'status', 'created_at'}}\n"
       "v4 = {'request_required': {'user_id', 'amount'}, 'response': {'id', 'state', 'created_at'}}\n\n"
       "def backward_compatible(old, new):\n"
       "    \"\"\"Ескі клиенттер жаңа сервермен жұмыс істей ала ма?\"\"\"\n"
       "    extra_required = new['request_required'] - old['request_required']\n"
       "    lost_fields = old['response'] - new['response']\n"
       "    return not extra_required and not lost_fields, sorted(extra_required), sorted(lost_fields)\n\n"
       "for name, new in [('v2', v2), ('v3', v3), ('v4', v4)]:\n"
       "    ok, req, lost = backward_compatible(v1, new)\n"
       "    print(name, 'үйлесімді' if ok else 'бұзады', req, lost)")

