ORDER = ("class Order:\n"
         "    \"\"\"Агрегат. Инварианттар: (1) total == жолдардың сомасы; (2) total <= limit;\n"
         "    (3) төленген тапсырыс өзгермейді. Күй тек әдістер арқылы өзгереді.\"\"\"\n"
         "    def __init__(self, limit):\n"
         "        self._lines, self._total, self._limit, self._paid = {}, 0, limit, False\n"
         "    def add(self, sku, price, qty):\n"
         "        if self._paid:\n"
         "            raise ValueError('төленген тапсырыс өзгермейді')\n"
         "        if price <= 0 or qty <= 0:\n"
         "            raise ValueError('баға мен саны оң болуы керек')\n"
         "        if self._total + price * qty > self._limit:\n"
         "            raise ValueError('лимиттен асады')\n"
         "        p, q = self._lines.get(sku, (price, 0))\n"
         "        self._lines[sku] = (price, q + qty)\n"
         "        self._total += price * qty\n"
         "    def pay(self):\n"
         "        self._paid = True\n"
         "    def check(self):\n"
         "        return self._total == sum(p * q for p, q in self._lines.values()) and self._total <= self._limit\n\n"
         "o = Order(limit=10000)\n"
         "o.add('кітап', 3000, 2)\n"
         "o.add('қалам', 500, 4)\n"
         "for args in [('ноутбук', 9000, 1), ('қалам', -1, 1)]:\n"
         "    try:\n"
         "        o.add(*args)\n"
         "    except ValueError as e:\n"
         "        print('бас тартылды:', e)\n"
         "o.pay()\n"
         "try:\n"
         "    o.add('дәптер', 100, 1)\n"
         "except ValueError as e:\n"
         "    print('бас тартылды:', e)\n"
         "print(o._total, o.check())")

